<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Foundry\SubordinatePersonaAuthorshipCommissionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:foundry:dispatch-subordinate-authorship',description:'Dispatch bounded Hagiography and Studium authorship for one subordinate Persona specification')]
final class FoundryDispatchSubordinateAuthorshipCommand extends Command{public function __construct(private readonly SubordinatePersonaAuthorshipCommissionService$service){parent::__construct();}protected function configure():void{$this->addArgument('specification-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->service->dispatch((string)$i->getArgument('specification-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if((bool)$i->getOption('json')){$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return self::SUCCESS;}$o->writeln('<info>SUBORDINATE_AUTHORSHIP_COMMISSIONS_ISSUED</info> '.$r['specification_id']);foreach($r['commissions']as$c)$o->writeln('- '.$c['office'].' '.$c['commission_id'].' '.$c['status']);$o->writeln('Authorship authority: PRESENT; PENDING RECIPIENT ACCEPTANCE');$o->writeln('Persona assembly authority: NOT GRANTED');$o->writeln('Persona approval authority: NOT GRANTED');$o->writeln('Profile approval authority: NOT GRANTED');$o->writeln('Spawning authority: NOT GRANTED');$o->writeln('Admission authority: NOT GRANTED');$o->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;}}
